    """Pick the best human-readable counterparty token from a delimited narration."""
    def _pick(text):
        if not isinstance(text, str) or not text:
            return ""
        parts = re.split(re.escape(sep)|r"\s{2,}", text) if sep else [text]
        if sep:
            parts = text.split(sep)
        candidates = []
        for p in parts:
            p = (p or "").strip(" -~*:")
            if not p:
                continue
            if not re.search(r"[A-Za-z]{3,}", p):
                continue
            if re.search(skip_re, p, re.I):
                continue
