            candidates.append(p)
        for p in candidates:
            if " " in p and re.search(r"[A-Za-z]{2,}\s+[A-Za-z]{2,}", p):
                return p
        for p in candidates:
            if re.match(r"^[A-Za-z][A-Za-z. ]*$", p) and len(p) >= 3:
                return p
        return candidates[0] if candidates else ""
    return description.apply(_pick)

